import React, { useState, useEffect } from 'react';
import { Container, Grid, Box, Typography, CircularProgress, CssBaseline, createTheme, ThemeProvider } from '@mui/material';
import { fetchDocuments, submitQuestion } from './api'; // Import from our new API file

import Header from './components/Header';
import QuestionInput from './components/QuestionInput';
import AnswerDisplay from './components/AnswerDisplay';
import SystemFeatures from './components/SystemFeatures';
import DocumentUploader from './components/DocumentUploader';

const theme = createTheme({
  palette: {
    primary: {
      main: '#4a69bd',
    },
    secondary: {
      main: '#6a89cc',
    },
  },
});

function App() {
  const [documents, setDocuments] = useState([]);
  const [selectedDocument, setSelectedDocument] = useState('');
  const [loading, setLoading] = useState(false);
  const [documentLoading, setDocumentLoading] = useState(true);
  const [question, setQuestion] = useState('');
  const [answer, setAnswer] = useState('');
  const [questionType, setQuestionType] = useState('');
  const [sources, setSources] = useState([]);
  const [processingTime, setProcessingTime] = useState(0);
  const [error, setError] = useState('');

  // Load documents on mount
  useEffect(() => {
    const loadDocuments = async () => {
      try {
        setDocumentLoading(true);
        console.log("Fetching documents...");
        const response = await fetchDocuments();
        console.log("Documents response:", response);

        setDocuments(response.documents || []);

        // Select the first document if available
        if (response.documents && response.documents.length > 0) {
          setSelectedDocument(response.documents[0].id);
        }
        setError('');
      } catch (err) {
        console.error('Error fetching documents:', err);
        setError('Failed to load documents');
      } finally {
        setDocumentLoading(false);
      }
    };

    loadDocuments();
  }, []);

  const handleQuestionSubmit = async (questionText, documentId) => {
    setQuestion(questionText);
    setAnswer('');
    setSources([]);
    setQuestionType('');
    setProcessingTime(0);
    setLoading(true);
    setError('');

    try {
      const response = await submitQuestion(questionText, documentId);

      setAnswer(response.answer);
      setQuestionType(response.question_type);
      setSources(response.sources);
      setProcessingTime(response.processing_time);
    } catch (err) {
      console.error('Error processing question:', err);
      if (err.response) {
        setError(`Error: ${err.response.data?.detail || err.response.status}`);
      } else if (err.request) {
        setError('Could not connect to server');
      } else {
        setError(`Error: ${err.message}`);
      }
    } finally {
      setLoading(false);
    }
  };

  const handleUploadSuccess = (documentData) => {
    console.log("Upload successful, adding document to list:", documentData);
    setDocuments(prev => [...prev, documentData]);
    setSelectedDocument(documentData.document_id);
    setError('');
  };

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <Box sx={{ display: 'flex', flexDirection: 'column', minHeight: '100vh' }}>
        <Header />
        <Container maxWidth="lg" sx={{ mt: 4, mb: 4, flexGrow: 1 }}>
          {documentLoading ? (
            <Box sx={{ display: 'flex', justifyContent: 'center', mt: 8 }}>
              <CircularProgress />
            </Box>
          ) : (
            <Grid container spacing={3}>
              <Grid item xs={12} md={8}>
                {documents.length === 0 ? (
                  <Box sx={{ mb: 3 }}>
                    <Typography variant="h6" gutterBottom>
                      No Documents Available
                    </Typography>
                    <Typography variant="body1">
                      Please upload a protocol document to get started.
                    </Typography>
                    {error && (
                      <Typography color="error" sx={{ mt: 2 }}>
                        {error}
                      </Typography>
                    )}
                  </Box>
                ) : (
                  <QuestionInput 
                    documents={documents}
                    selectedDocument={selectedDocument}
                    setSelectedDocument={setSelectedDocument}
                    onSubmit={handleQuestionSubmit}
                    loading={loading}
                  />
                )}

                {error && !documentLoading && (
                  <Box sx={{ mt: 2, mb: 2 }}>
                    <Typography color="error">{error}</Typography>
                  </Box>
                )}

                <AnswerDisplay 
                  question={question}
                  answer={answer}
                  loading={loading}
                  sources={sources}
                  questionType={questionType}
                  processingTime={processingTime}
                />

                <DocumentUploader onUploadSuccess={handleUploadSuccess} />
              </Grid>

              <Grid item xs={12} md={4}>
                <SystemFeatures />
              </Grid>
            </Grid>
          )}
        </Container>
      </Box>
    </ThemeProvider>
  );
}

export default App;
